static void addEdge(int a, int b) {
    to[edgeCount] = b;
    nextEdge[edgeCount] = head[a];
    head[a] = edgeCount++;
}

static void buildCentroid(int entry, int level, int parentCentroid) {
    int top = 0, count = 0;
    componentStack[top++] = entry;
    tempParent[entry] = -1;

    while (top > 0) {
        int v = componentStack[--top];
        componentOrder[count++] = v;

        for (int e = head[v]; e != -1; e = nextEdge[e]) {
            int w = to[e];
            if (removed[w] || w == tempParent[v]) continue;
            tempParent[w] = v;
            componentStack[top++] = w;
        }
    }

    for (int i = count - 1; i >= 0; --i) {
        int v = componentOrder[i];
        subtreeSize[v] = 1;
        if (tempParent[v] != -1)
            subtreeSize[tempParent[v]] += subtreeSize[v];
    }

    int centroid = entry;
    for (int i = 0; i < count; ++i) {
        int v = componentOrder[i];
        int largest = count - subtreeSize[v];

        for (int e = head[v]; e != -1; e = nextEdge[e]) {
            int w = to[e];
